24	import com.example.starter.pension.repo.InstallmentRepository.NewInstallment;
25	import com.example.starter.pension.repo.InstructionRepository;
26	import com.example.starter.pension.repo.LedgerRepository;
27	import com.example.starter.pension.repo.MemberRepository;
28	import com.example.starter.pension.repo.PlanRepository;
29	import com.example.starter.pension.support.TimeProvider;
30	import com.example.starter.pension.web.ApiException;
31	import org.springframework.dao.DataIntegrityViolationException;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.stereotype.Service;
34	import org.springframework.transaction.PlatformTransactionManager;
35	import org.springframework.transaction.support.TransactionTemplate;
36	
37	import java.util.List;
38	import java.util.Locale;
39	import java.util.UUID;
40	
41	/**
42	 * 年金权益归属与分期支付应用服务实现。
43	 *
44	 * <p>关键事务边界：</p>
45	 * <ul>
46	 *     <li>申请受理：成员行锁 + requestId/进行中成员唯一索引，保证同成员并发唯一受理，
47	 *     缴费快照在同事务冻结；</li>
48	 *     <li>末期出款：成员出款入账、未归属企业缴费划回、计划结清同一事务提交或回滚；</li>
49	 *     <li>支付指令：requestId 唯一索引 + 期次行锁，每期最多出款一次，同键重放首次结果。</li>
50	 * </ul>
51	 */
52	@Service
53	public class PensionServiceImpl implements PensionService {
54	
55	    private final MemberRepository memberRepository;
56	    private final ContributionRepository contributionRepository;
57	    private final PlanRepository planRepository;
58	    private final InstallmentRepository installmentRepository;
59	    private final InstructionRepository instructionRepository;
60	    private final LedgerRepository ledgerRepository;
61	    private final BankGateway bankGateway;
62	    private final VestingCalculator vestingCalculator;
63	    private final InstallmentScheduler installmentScheduler;
64	    private final TimeProvider timeProvider;
65	    private final TransactionTemplate transactionTemplate;
66	
67	    public PensionServiceImpl(MemberRepository memberRepository,
68	                              ContributionRepository contributionRepository,
69	                              PlanRepository planRepository,
70	                              InstallmentRepository installmentRepository,
71	                              InstructionRepository instructionRepository,
72	                              LedgerRepository ledgerRepository,
73	                              BankGateway bankGateway,
74	                              VestingCalculator vestingCalculator,
75	                              InstallmentScheduler installmentScheduler,
76	                              TimeProvider timeProvider,
77	                              PlatformTransactionManager transactionManager) {
78	        this.memberRepository = memberRepository;
79	        this.contributionRepository = contributionRepository;
80	        this.planRepository = planRepository;
81	        this.installmentRepository = installmentRepository;
82	        this.instructionRepository = instructionRepository;
83	        this.ledgerRepository = ledgerRepository;
84	        this.bankGateway = bankGateway;
85	        this.vestingCalculator = vestingCalculator;
86	        this.installmentScheduler = installmentScheduler;
87	        this.timeProvider = timeProvider;
88	        this.transactionTemplate = new TransactionTemplate(transactionManager);
89	    }
90	
91	    @Override
92	    public void upsertMember(MemberUpsertRequest request) {
93	        memberRepository.upsert(request.memberNo(), request.name(), request.hireDate(), request.status());
94	    }
95	
96	    @Override
97	    public void addContribution(ContributionRequest request) {
98	        MemberRow member = requireMember(request.memberNo());
99	        contributionRepository.insert(member.id(), request.contributionType(), request.amountCents(),
100	                request.contributionDate(), request.period());
101	    }
102	
103	    @Override
104	    public PlanResponse applyPayout(PayoutRequest request) {
105	        PlanRow replay = planRepository.findByRequestId(request.requestId()).orElse(null);
106	        if (replay != null) {
107	            return replayOrConflict(replay, request.memberNo(), request.reason(),
108	                    request.installmentType(), request.requestDate().toString(), null);
109	        }
110	        try {
111	            return transactionTemplate.execute(status -> doApply(request));
112	        } catch (DataIntegrityViolationException ex) {
113	            return handleApplyIntegrityViolation(request, null);
114	        }
115	    }
116	
117	    @Override
118	    public PlanResponse applySupplementary(SupplementaryPayoutRequest request) {
119	        PlanRow replay = planRepository.findByRequestId(request.requestId()).orElse(null);
120	        if (replay != null) {
121	            return replayOrConflict(replay, request.memberNo(), request.reason(),
122	                    request.installmentType(), request.requestDate().toString(), request.originalPlanNo());
123	        }
124	        try {
125	            return transactionTemplate.execute(status -> doApplySupplementary(request));
126	        } catch (DataIntegrityViolationException ex) {
127	            return handleApplyIntegrityViolation(null, request);
128	        }
129	    }
130	
131	    @Override
132	    public PlanResponse getPlan(String planNo) {
133	        PlanRow plan = requirePlan(planNo);
134	        return toPlanResponse(plan);
135	    }
136	
137	    @Override
138	    public PaymentResultResponse payInstallment(PaymentInstructionRequest request) {
139	        InstructionRow replay = instructionRepository.findByRequestId(request.requestId()).orElse(null);
140	        if (replay != null) {
141	            PlanRow plan = planRepository.findById(replay.planId())
142	                    .orElseThrow(() -> new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,
143	                            "PLAN_MISSING", "指令关联计划缺失"));
144	            return paymentReplay(request, plan, replay);
145	        }
146	        try {
147	            return transactionTemplate.execute(status -> doPay(request));
148	        } catch (DataIntegrityViolationException ex) {
149	            InstructionRow winner = instructionRepository.findByRequestId(request.requestId()).orElse(null);
150	            if (winner == null) {
151	                throw new ApiException(HttpStatus.CONFLICT, "PAYMENT_REJECTED",
152	                        "支付被唯一约束拒绝，请重试");
153	            }
154	            PlanRow plan = planRepository.findById(winner.planId()).orElseThrow();
155	            return paymentReplay(request, plan, winner);
156	        }
157	    }
158	
159	    @Override
160	    public SettleResponse settle(String planNo) {
161	        return transactionTemplate.execute(status -> {
162	            PlanRow plan = planRepository.findByPlanNo(planNo)
163	                    .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "PLAN_NOT_FOUND",
164	                            "支付计划不存在: " + planNo));
165	            PlanRow locked = planRepository.lockById(plan.id()).orElseThrow();
166	            if (locked.status() == PlanStatus.SETTLED) {
167	                return buildSettleResponse(locked, true);
168	            }
169	            List<InstallmentRow> installments = installmentRepository.findByPlanId(locked.id());
170	            boolean allPaid = installments.stream().allMatch(i -> i.status() == InstallmentStatus.PAID);
171	            if (!allPaid) {
172	                throw new ApiException(HttpStatus.CONFLICT, "PLAN_NOT_PAYABLE_COMPLETE",
173	                        "存在未完成期次，计划不能结清");
174	            }
175	            ensureEnterpriseReturned(locked);
176	            planRepository.markSettled(locked.id(), timeProvider.nowUtc());
177	            PlanRow refreshed = planRepository.findByPlanNo(planNo).orElseThrow();
178	            return buildSettleResponse(refreshed, false);
179	        });
180	    }
181	
182	    // ------------------------------------------------------------------
183	    // 申请受理（原始 / 补发）
184	    // ------------------------------------------------------------------
185	
186	    private PlanResponse doApply(PayoutRequest request) {
187	        MemberRow member = requireMember(request.memberNo());
188	        memberRepository.lockById(member.id());
189	        PlanRow concurrent = planRepository.findByRequestId(request.requestId()).orElse(null);
190	        if (concurrent != null) {
191	            return replayOrConflict(concurrent, request.memberNo(), request.reason(),
192	                    request.installmentType(), request.requestDate().toString(), null);
193	        }
194	        if (planRepository.countActiveByMember(member.id()) > 0) {
195	            throw new ApiException(HttpStatus.CONFLICT, "ACTIVE_PLAN_EXISTS",
196	                    "该成员已存在进行中的支付计划");
197	        }
198	        if (planRepository.countByMember(member.id()) > 0) {
199	            throw new ApiException(HttpStatus.CONFLICT, "MEMBER_ALREADY_HAS_PLAN",
200	                    "该成员已存在历史支付计划，结清后补缴须走补发流程并引用原计划号");
201	        }
202	        validateReason(member, request.reason());
203	        List<ContributionRow> unfrozen = contributionRepository.findUnfrozen(member.id());
204	        PlanRow plan = createPlan(request.requestId(), member, request.reason(),
205	                request.installmentType(), request.requestDate(), unfrozen, null);
206	        return toPlanResponse(plan);
207	    }
208	
209	    private PlanResponse doApplySupplementary(SupplementaryPayoutRequest request) {
210	        MemberRow member = requireMember(request.memberNo());
211	        PlanRow original = planRepository.findByPlanNo(request.originalPlanNo())
212	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "ORIGINAL_PLAN_NOT_FOUND",
213	                        "原支付计划不存在: " + request.originalPlanNo()));
214	        if (original.memberId() != member.id()) {
215	            throw new ApiException(HttpStatus.CONFLICT, "ORIGINAL_PLAN_MEMBER_MISMATCH",
216	                    "原计划属于其他成员，不能作为补发引用");
217	        }
218	        if (original.status() != PlanStatus.SETTLED) {
219	            throw new ApiException(HttpStatus.CONFLICT, "ORIGINAL_PLAN_NOT_SETTLED",
220	                    "只有已结清（终态）计划才能发起补发，且补发不得改动原计划");
221	        }
222	        validateReason(member, request.reason());
223	        memberRepository.lockById(member.id());
224	        PlanRow concurrent = planRepository.findByRequestId(request.requestId()).orElse(null);
225	        if (concurrent != null) {
226	            return replayOrConflict(concurrent, request.memberNo(), request.reason(),
227	                    request.installmentType(), request.requestDate().toString(), request.originalPlanNo());
228	        }
229	        if (planRepository.countActiveByMember(member.id()) > 0) {
230	            throw new ApiException(HttpStatus.CONFLICT, "ACTIVE_PLAN_EXISTS",
231	                    "该成员已存在进行中的支付计划");
232	        }
233	        List<ContributionRow> unfrozen = contributionRepository.findUnfrozen(member.id());
234	        if (unfrozen.isEmpty()) {
235	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "NO_SUPPLEMENTARY_CONTRIBUTIONS",
236	                    "没有结清后补缴且未冻结的历史缴费可用于补发");
237	        }
238	        PlanRow plan = createPlan(request.requestId(), member, request.reason(),
239	                request.installmentType(), request.requestDate(), unfrozen, original.planNo());
240	        return toPlanResponse(plan);
241	    }
242	
243	    private PlanRow createPlan(String requestId, MemberRow member, PayoutReason reason,
244	                               InstallmentType installmentType, java.time.LocalDate requestDate,
245	                               List<ContributionRow> contributions, String originalPlanNo) {
246	        if (contributions.isEmpty()) {
247	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "NO_FREEZABLE_CONTRIBUTIONS",
248	                    "没有可冻结进权益快照的缴费，无法受理支付申请");
249	        }
250	        long personal = contributions.stream()
251	                .filter(c -> c.type() == com.example.starter.pension.domain.ContributionType.PERSONAL)
252	                .mapToLong(ContributionRow::amountCents)
253	                .sum();
254	        long enterprise = contributions.stream()
255	                .filter(c -> c.type() == com.example.starter.pension.domain.ContributionType.ENTERPRISE)
256	                .mapToLong(ContributionRow::amountCents)
257	                .sum();
258	
259	        int hireYears = vestingCalculator.hireYears(member.hireDate(), requestDate);
260	        int ratioBp = vestingCalculator.vestedRatioBp(hireYears);
261	        long vestedEnterprise = vestingCalculator.vestedEnterprise(enterprise, ratioBp);
262	        long vestedTotal = Math.addExact(personal, vestedEnterprise);
263	        long unvested = enterprise - vestedEnterprise;
264	
265	        String fingerprint = Fingerprints.sha256(requestId, member.memberNo(), reason.name(),
266	                installmentType.name(), requestDate.toString(),
267	                originalPlanNo == null ? "" : originalPlanNo);
268	
269	        int count = installmentType.count();
270	        List<NewInstallment> schedule = installmentScheduler.schedule(
271	                vestedTotal, count, requestDate.withDayOfMonth(1));
272	        long scheduleSum = schedule.stream().mapToLong(NewInstallment::amountCents).sum();
273	        if (scheduleSum != vestedTotal) {
274	            throw new IllegalStateException("分期总额与归属权益快照不一致");
275	        }
276	
277	        String planNo = newPlanNo();
278	        PlanRow plan = new PlanRow(0L, planNo, requestId, member.id(), reason, installmentType,
279	                fingerprint, requestDate, hireYears, ratioBp, personal, enterprise,
280	                vestedEnterprise, vestedTotal, unvested, count, PlanStatus.ACCEPTED,
281	                member.id(), false, originalPlanNo, originalPlanNo != null, null);
282	        long planId = planRepository.insert(plan);
283	
284	        List<Long> contributionIds = contributions.stream().map(ContributionRow::id).toList();
285	        int frozen = contributionRepository.freeze(contributionIds, planId);
286	        if (frozen != contributions.size()) {
287	            throw new ApiException(HttpStatus.CONFLICT, "CONCURRENT_SNAPSHOT_FREEZE",
288	                    "缴费快照被并发申请抢先冻结，唯一受理失败");
289	        }
290	        installmentRepository.insertBatch(planId, schedule);
291	        return planRepository.findById(planId)
292	                .orElseThrow(() -> new IllegalStateException("计划插入后无法回读"));
293	    }
294	
295	    // ------------------------------------------------------------------
296	    // 单期出款
297	    // ------------------------------------------------------------------
298	
299	    private PaymentResultResponse doPay(PaymentInstructionRequest request) {
300	        PlanRow plan = planRepository.findByPlanNo(request.planNo())
301	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "PLAN_NOT_FOUND",
302	                        "支付计划不存在: " + request.planNo()));
303	        PlanRow lockedPlan = planRepository.lockById(plan.id()).orElseThrow();
304	        InstructionRow lockedReplay = instructionRepository.findByRequestId(request.requestId())
305	                .orElse(null);
306	        if (lockedReplay != null) {
307	            return paymentReplay(request, lockedPlan, lockedReplay);
308	        }
309	        InstallmentRow installment = installmentRepository
310	                .lockByPlanAndSeq(lockedPlan.id(), request.seqNo())
311	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "INSTALLMENT_NOT_FOUND",
312	                        "期次不存在: " + request.seqNo()));
313	        if (installment.status() == InstallmentStatus.PAID) {
314	            throw new ApiException(HttpStatus.CONFLICT, "INSTALLMENT_ALREADY_PAID",
315	                    "该期次已出款，每期最多出款一次");
316	        }
317	
318	        String fingerprint = Fingerprints.sha256(request.requestId(), lockedPlan.planNo(),
319	                Integer.toString(request.seqNo()), Long.toString(installment.amountCents()));
320	        int attempts = installment.attempts() + 1;
321	        boolean success = bankGateway.payout(lockedPlan.planNo(), request.seqNo(),
322	                installment.amountCents(), request.forceFail());
323	
324	        if (success) {
325	            int paid = installmentRepository.markPaidIfNotYet(
326	                    installment.id(), attempts, timeProvider.nowUtc());
327	            if (paid == 0) {
328	                throw new ApiException(HttpStatus.CONFLICT, "INSTALLMENT_ALREADY_PAID",
329	                        "该期次已出款，每期最多出款一次");
330	            }
331	            ledgerRepository.insertMemberPayout(lockedPlan.id(), installment.id(),
332	                    installment.amountCents());
333	            instructionRepository.insert(new InstructionRow(0L, request.requestId(), lockedPlan.id(),
334	                    installment.id(), request.seqNo(), installment.amountCents(), fingerprint,
335	                    true, timeProvider.nowUtc()));
336	            planRepository.markInProgress(lockedPlan.id());
337	
338	            List<InstallmentRow> all = installmentRepository.findByPlanId(lockedPlan.id());
339	            boolean allPaid = all.stream().allMatch(i -> i.status() == InstallmentStatus.PAID);
340	            if (allPaid) {
341	                ensureEnterpriseReturned(lockedPlan);
342	                planRepository.markSettled(lockedPlan.id(), timeProvider.nowUtc());
343	            }
344	            InstallmentRow refreshed = installmentRepository.findByPlanAndSeq(lockedPlan.id(), request.seqNo()).orElseThrow();
345	            return new PaymentResultResponse(request.requestId(), lockedPlan.planNo(), request.seqNo(),
346	                    installment.amountCents(), true, false, refreshed.paidAt(), installment.dueDate());
347	        }
348	
349	        installmentRepository.markFailed(installment.id(), attempts);
350	        instructionRepository.insert(new InstructionRow(0L, request.requestId(), lockedPlan.id(),
351	                installment.id(), request.seqNo(), installment.amountCents(), fingerprint,
352	                false, timeProvider.nowUtc()));
353	        return new PaymentResultResponse(request.requestId(), lockedPlan.planNo(), request.seqNo(),
354	                installment.amountCents(), false, false, null, installment.dueDate());
355	    }
356	
357	    /**
358	     * 未归属企业缴费划回：以计划标志位条件更新为闸门，保证只划转一次；
359	     * 与末期成员出款处于同一事务。
360	     */
361	    private void ensureEnterpriseReturned(PlanRow lockedPlan) {
362	        if (lockedPlan.unvestedReturnCents() <= 0 || lockedPlan.enterpriseReturned()) {
363	            return;
364	        }
365	        int flagged = planRepository.markEnterpriseReturned(lockedPlan.id());
366	        if (flagged > 0) {
367	            ledgerRepository.insertEnterpriseReturn(lockedPlan.id(), lockedPlan.unvestedReturnCents());
368	        }
369	    }
370	
371	    // ------------------------------------------------------------------
372	    // 幂等与冲突
373	    // ------------------------------------------------------------------
374	
375	    private PaymentResultResponse paymentReplay(PaymentInstructionRequest request,
376	                                                PlanRow plan, InstructionRow first) {
377	        if (!plan.planNo().equals(request.planNo()) || first.seqNo() != request.seqNo()) {
378	            throw new ApiException(HttpStatus.CONFLICT, "IDEMPOTENCY_CONFLICT",
379	                    "支付指令 requestId 已存在但业务参数不一致");
380	        }
381	        InstallmentRow installment = installmentRepository
382	                .findByPlanAndSeq(first.planId(), first.seqNo())
383	                .orElseThrow(() -> new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,
384	                        "INSTALLMENT_MISSING", "指令关联期次缺失"));
385	        return new PaymentResultResponse(request.requestId(), plan.planNo(), first.seqNo(),
386	                first.amountCents(), first.success(), true, installment.paidAt(),
387	                installment.dueDate());
388	    }
389	
390	    private PlanResponse replayOrConflict(PlanRow existing, String memberNo, PayoutReason reason,
391	                                          InstallmentType installmentType, String requestDate,
392	                                          String originalPlanNo) {
393	        MemberRow member = memberRepository.findById(existing.memberId()).orElseThrow();
394	        String expectedFingerprint = Fingerprints.sha256(existing.requestId(), member.memberNo(),
395	                reason.name(), installmentType.name(), requestDate,
396	                originalPlanNo == null ? "" : originalPlanNo);
397	        if (!member.memberNo().equals(memberNo) || !existing.fingerprint().equals(expectedFingerprint)) {
398	            throw new ApiException(HttpStatus.CONFLICT, "IDEMPOTENCY_CONFLICT",
399	                    "requestId 已存在但业务字段不一致，拒绝产生新计划");
400	        }
401	        return toPlanResponse(existing);
402	    }
403	
404	    private PlanResponse handleApplyIntegrityViolation(PayoutRequest normalRequest,
405	                                                       SupplementaryPayoutRequest supplementaryRequest) {
406	        String requestId = normalRequest != null ? normalRequest.requestId() : supplementaryRequest.requestId();
407	        PlanRow winner = planRepository.findByRequestId(requestId).orElse(null);
408	        if (winner == null) {
409	            throw new ApiException(HttpStatus.CONFLICT, "ACTIVE_PLAN_EXISTS",
410	                    "该成员已存在进行中的支付计划，并发申请仅唯一受理");
411	        }
412	        if (normalRequest != null) {
413	            return replayOrConflict(winner, normalRequest.memberNo(), normalRequest.reason(),
414	                    normalRequest.installmentType(), normalRequest.requestDate().toString(), null);
415	        }
416	        return replayOrConflict(winner, supplementaryRequest.memberNo(), supplementaryRequest.reason(),
417	                supplementaryRequest.installmentType(), supplementaryRequest.requestDate().toString(),
418	                supplementaryRequest.originalPlanNo());
419	    }
420	
421	    // ------------------------------------------------------------------
422	    // 视图与校验
423	    // ------------------------------------------------------------------
424	
425	    private MemberRow requireMember(String memberNo) {
426	        return memberRepository.findByNo(memberNo)
427	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "MEMBER_NOT_FOUND",
428	                        "成员不存在: " + memberNo));
429	    }
430	
431	    private PlanRow requirePlan(String planNo) {
432	        return planRepository.findByPlanNo(planNo)
433	                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "PLAN_NOT_FOUND",
434	                        "支付计划不存在: " + planNo));
435	    }
436	
437	    private void validateReason(MemberRow member, PayoutReason reason) {
438	        MemberStatus required = reason == PayoutReason.RESIGN
439	                ? MemberStatus.RESIGNED : MemberStatus.RETIRED;
440	        if (member.status() != required) {
441	            throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "REASON_STATUS_MISMATCH",
442	                    "支付事由与成员状态不一致：" + reason + " 要求成员状态为 " + required);
443	        }
444	    }
445	
446	    private PlanResponse toPlanResponse(PlanRow plan) {
447	        MemberRow member = memberRepository.findById(plan.memberId()).orElseThrow();
448	        List<PlanResponse.InstallmentView> views = installmentRepository.findByPlanId(plan.id())
449	                .stream()
450	                .map(i -> new PlanResponse.InstallmentView(i.seqNo(), i.dueDate(),
451	                        i.amountCents(), i.status().name(), i.attempts()))
452	                .toList();
453	        String ratioPercent = String.format(Locale.ROOT, "%.2f", plan.vestedRatioBp() / 100.0);
454	        return new PlanResponse(plan.planNo(), plan.originalPlanNo(), plan.supplementary(),
455	                plan.requestId(), member.memberNo(), plan.reason(), plan.installmentType(),
456	                plan.requestDate(), plan.hireYears(), ratioPercent, plan.personalAmountCents(),
457	                plan.enterpriseAmountCents(), plan.vestedEnterpriseCents(), plan.vestedTotalCents(),
458	                plan.unvestedReturnCents(), plan.status(), plan.enterpriseReturned(),
459	                plan.settledAt(), views);
460	    }
461	
462	    private SettleResponse buildSettleResponse(PlanRow plan, boolean replayed) {
463	        long paid = ledgerRepository.sumMemberPayouts(plan.id());
464	        long returned = ledgerRepository.sumEnterpriseReturns(plan.id());
465	        return new SettleResponse(plan.planNo(), plan.status(), replayed,
466	                plan.vestedTotalCents(), paid, returned, plan.settledAt());
467	    }
468	
469	    private static String newPlanNo() {
470	        return "PL-" + UUID.randomUUID().toString().replace("-", "").substring(0, 16).toUpperCase(Locale.ROOT);
471	    }
472	}
