                           SET status = 'SETTLED', active_member_id = NULL, settled_at = :settledAt
                         WHERE id = :planId AND status <> 'SETTLED'""")
                .param("settledAt", Timestamp.from(settledAt.toInstant()))
                .param("planId", planId)
                .update();
