    @Override
    public int markEnterpriseReturned(long planId) {
        return jdbcClient.sql("""
                        UPDATE payout_plan
                           SET enterprise_returned = TRUE
                         WHERE id = :planId AND enterprise_returned = FALSE""")
                .param("planId", planId)
                .update();
