package com.example.starter.pension.bank;

import org.springframework.stereotype.Component;

/**
 * 本地（进程内）托管行模拟实现：无外部银行、无网络 IO。
 * forceFail=true 时确定性返回失败，用于失败重试与事务回滚测试；其余返回成功。
 */
@Component
public class LocalBankGateway implements BankGateway {

    @Override
    public boolean payout(String planNo, int seqNo, long amountCents, boolean forceFail) {
        if (forceFail) {
            return false;
        }
        return true;
    }
}

package com.example.starter.pension.bank;

/**
 * 托管银行出款网关。本地实现不依赖任何外部托管行，仅按指令确定性返回出款结果。
 */
public interface BankGateway {

    /**
     * 发起一笔成员账户出款。
     *
     * @param planNo      计划号
     * @param seqNo       期次序号
     * @param amountCents 出款金额，单位：分
     * @param forceFail   是否模拟出款失败
     * @return true 出款成功；false 出款失败（期次可换 requestId 重试）
     */
    boolean payout(String planNo, int seqNo, long amountCents, boolean forceFail);
}

package com.example.starter.pension.domain;

/**
 * 分期期次状态。
 */
public enum InstallmentStatus {

    /** 待付。 */
    PENDING,
    /** 已出款，终态，每期最多出款一次。 */
    PAID,
    /** 出款失败，可使用新的指令 requestId 重试。 */
    FAILED
}

